// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { config } from "dotenv";
import fs from "node:fs";
import path from "node:path";
import { defineConfig } from "prisma/config";

// `dotenv/config` only reads `.env`, but this project keeps its local
// configuration in `.env.local` (Next.js convention). Without this, Prisma
// CLI commands run from the shell see no DATABASE_URL and fail with
// "The datasource.url property is required in your Prisma config file".
for (const file of [".env.local", ".env"]) {
  const full = path.join(process.cwd(), file);
  if (fs.existsSync(full)) config({ path: full, override: false });
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
